import{_ as e,o,c,a2 as t}from"./chunks/framework.BM5YPQmL.js";const b=JSON.parse('{"title":"构建系统全量参考（维护者手册）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/release/build-reference.md","filePath":"zh/release/build-reference.md"}'),r={name:"zh/release/build-reference.md"};function a(s,d,i,l,n,_){return o(),c("div",null,[...d[0]||(d[0]=[t(`<h1 id="构建系统全量参考-维护者手册" tabindex="-1">构建系统全量参考（维护者手册） <a class="header-anchor" href="#构建系统全量参考-维护者手册" aria-label="Permalink to &quot;构建系统全量参考（维护者手册）&quot;">​</a></h1><p>Open Cube OS 构建的完整机制级参考：每一个伪目标、每一个内部 文件目标、每一个变量、每一个 <code>-D</code> 宏、每一个按文件的优化覆盖， 以及并行度 / 编译缓存机制。配套页面：<a href="./guard-scripts.html">guard-scripts</a> （检查脚本）、<a href="./ci-gates.html">ci-gates</a>（CI 与发布链）、 <a href="./tool-inventory.html">tool-inventory</a>（<code>tools/</code> 全部 117 个文件）。</p><p>本文覆盖的构建文件：<code>Makefile</code>（顶层）、<code>ocire/ocire.mk</code>、 <code>ocbl/ocbl.mk</code>、<code>ocse/ocse.mk</code>、<code>ocos/kernel/arch/{arm64,riscv}/build.mk</code>， 以及入口封装 <code>tools/build.sh</code> 和 <code>build.ps1</code>。</p><h2 id="_1-架构分派与入口" tabindex="-1">1. 架构分派与入口 <a class="header-anchor" href="#_1-架构分派与入口" aria-label="Permalink to &quot;1. 架构分派与入口&quot;">​</a></h2><p><code>ARCH ?= x86_64</code>。任何超出 <code>x86_64 arm64 riscv</code> 的取值都会立即以 <code>$(error unsupported ARCH &#39;&lt;ARCH&gt;&#39; - supported: x86_64 arm64 riscv)</code> 失败——make 在运行任何一条命令之前即中止。</p><ul><li><code>ARCH=x86_64</code>（默认）：<code>Makefile</code> 的完整主体——内核、ISO、 src zip、OTA、QEMU、配置、缓存、测试——外加三个组件包含 （<code>ocire.mk</code>、<code>ocbl.mk</code>、<code>ocse.mk</code>）。</li><li><code>ARCH=arm64</code> / <code>ARCH=riscv</code>：整个 x86_64 主体被跳过，改为包含 <code>ocos/kernel/arch/$(ARCH)/build.mk</code>（仅 bring-up 壳；见 §7）。</li></ul><p>三个等价入口构建同一产物：</p><table tabindex="0"><thead><tr><th>入口</th><th>相对裸 make 的附加能力</th></tr></thead><tbody><tr><td><code>make &lt;target&gt;</code></td><td>无——事实来源</td></tr><tr><td><code>tools/build.sh &lt;target&gt;</code></td><td>依赖检测（每条命令对应的精确 Debian 包）、<code>--install</code> apt 回退、免 root 的 <code>install-toolchain.sh</code> 提示、<code>OC_TOOLS</code> 自动发现（<code>/usr</code>、<code>$HOME/tools/grub</code>）、<code>JOBS</code> 并行度（默认 <code>nproc</code>）</td></tr><tr><td><code>build.ps1</code>（Windows）</td><td>经 WSL2（<code>wsl.exe</code> + <code>wslpath</code>）或 MSYS2/Git-Bash（<code>cygpath</code>）翻译成对 <code>tools/build.sh</code> 的调用；<code>-Target</code>（默认 <code>all</code>）、<code>-Install</code></td></tr></tbody></table><p><code>tools/build.sh</code> 还暴露可脚本化 API（WP-13 规范 8）： <code>build_all</code>、<code>build_iso</code>、<code>build_src</code>、<code>build_ota</code>、<code>config_load</code>、 <code>config_save</code>、<code>config_get</code>、<code>cache_lookup</code>、<code>cross_compile</code>、 <code>cross_toolchain_setup</code>——source 该脚本即可调用。</p><p><code>.DEFAULT_GOAL := kernel</code>：裸 <code>make</code> 只构建 <code>build/opencube.elf</code>。完整的 WP-13 流水线是 <code>make all</code>。</p><h2 id="_2-顶层伪目标-26-个" tabindex="-1">2. 顶层伪目标（26 个） <a class="header-anchor" href="#_2-顶层伪目标-26-个" aria-label="Permalink to &quot;2. 顶层伪目标（26 个）&quot;">​</a></h2><p>格式：<strong>触发 → 配方逻辑 → 失败后果。</strong></p><table tabindex="0"><thead><tr><th>#</th><th>目标</th><th>触发 / 前置条件</th><th>逻辑</th><th>失败时</th></tr></thead><tbody><tr><td>1</td><td><code>all</code></td><td><code>userprogs $(KERNEL_ISO) src-zip ota</code></td><td>WP-13 统一流水线；先重建内嵌程序（WP06g1 catch-2：<code>make all</code> 曾一次交付过期的 <code>userprogs_data.h</code>），然后内核 + ISO、确定性 src zip、OTA 包；打印四个产物路径</td><td>任一子门禁失败即停止流水线</td></tr><tr><td>2</td><td><code>kernel</code></td><td><code>$(KERNEL)</code> = <code>build/opencube.elf</code></td><td>WP-13 之前的语义：仅两阶段链接出 ELF（见 §3.2）</td><td>链接/编译错误即中止</td></tr><tr><td>3</td><td><code>iso</code></td><td><code>$(KERNEL_ISO)</code></td><td>经 <code>tools/build_iso.sh</code> 打包双固件 OCBL ISO；前置条件包含 <code>$(USERPROGS_HDR)</code>，因此单独 <code>make iso</code> 永远不会打包过期的内嵌程序（WP06g2）</td><td>打包脚本非零退出 → make 失败</td></tr><tr><td>4</td><td><code>src-zip</code></td><td>无（伪目标）</td><td><code>git ls-files</code> 经 <code>SRC_EXCLUDE</code> 过滤，tag <code>v$(OC_RELEASE_VERSION)</code> 存在时与该 tag 的树求交（<code>ls-tree -r</code> + <code>grep -Fx -f</code>），再 <code>git archive --format=zip</code>；HEAD 回退时打印一条响亮的 &quot;development cut, NOT a release asset&quot; 警告；<code>.srclist</code> 为空（非 git 检出）→ <code>exit 1</code> 并指引用 <code>make dist</code></td><td>非 git 树硬失败；HEAD 切片仅警告</td></tr><tr><td>5</td><td><code>ota</code></td><td><code>$(KERNEL) $(KERNEL_ISO)</code></td><td><code>tools/make_update_pkg.sh</code> → <code>dist/OpenCubeOS-&lt;ver&gt;-update.tar.gz</code>；ISO 是前置条件，因此&quot;旧 ISO + 新 OTA&quot;的组合无法产出（v2.0.0 修复）</td><td>脚本失败即中止</td></tr><tr><td>6</td><td><code>reproducible-check</code></td><td>无</td><td>clean→kernel→sha256，两轮；<code>cmp -s /tmp/.oc_repro_1.elf $(KERNEL)</code>；PASS 消息 + 两个哈希，或 FAIL + <code>cmp</code> 前 3 个差异字节 + <code>exit 1</code></td><td>任何字节差异即 exit 1</td></tr><tr><td>7–12</td><td><code>run-bios</code>、<code>run-uefi</code>、<code>run-bios-gui</code>、<code>run-uefi-gui</code>、<code>run-bios-persist</code>、<code>run-uefi-persist</code></td><td><code>$(KERNEL_ISO) $(ETC_IMG)</code></td><td>QEMU 启动：256M 内存、IDE <code>/etc</code> 盘、<code>-no-reboot</code>、串口 stdio。<code>-display none</code>（无头）、<code>-display gtk</code>（GUI——PS/2 键盘需要一个窗口来投递扫描码）、<code>-snapshot</code> 关闭（persist：<code>/etc/opencube.conf</code> 的编辑写回 <code>build/etc.img</code>，WP-09-fix5）。UEFI 变体把 <code>$(OVMF_FD)</code> 复制到 <code>build/OVMF_WORK.fd</code> 并作为 pflash 挂载</td><td>QEMU 退出码向上传播</td></tr><tr><td>13–14</td><td><code>shot-bios</code>、<code>shot-uefi</code></td><td><code>$(KERNEL_ISO)</code></td><td><code>tools/qemu_shot_vnc.py</code> 经 VNC 启动、monitor-screendump、用 PIL 把 PPM 转 PNG → <code>build/shot-{bios,uefi}.png</code></td><td>工具失败即中止</td></tr><tr><td>15</td><td><code>clean</code></td><td>无</td><td><code>rm -rf $(BUILD) $(DIST) $(ISO_DIR)/boot/opencube.elf $(GEN_DIR)/grub_boot_data.c</code>——删除目标文件、ELF、ISO、dist 产物、瞬态 stage-2 GRUB 数据</td><td>—</td></tr><tr><td>16</td><td><code>dist</code></td><td><code>userprogs-check $(KERNEL_ISO)</code></td><td>先过过期门禁（见下），然后带时间戳的 <code>zip -qr</code>（不是 git archive），内联排除（<code>build/</code>、<code>dist/</code>、<code>.git/</code>、<code>tools/push_to_git.py</code>、<code>releases/</code>、网站构建树、<code>ocos/kernel/generated/*</code>）、复制 ISO、<code>sha256sum</code> 边车文件</td><td>门禁失败在任何打包之前中止</td></tr><tr><td>17</td><td><code>defconfig</code></td><td>无</td><td>heredoc 写入带 <code>CONFIG_NVME=y CONFIG_AHCI=y CONFIG_VIRTIO_BLK=y</code> 的 <code>.config</code></td><td>—</td></tr><tr><td>18</td><td><code>menuconfig</code></td><td>无</td><td><code>tools/oc_menuconfig.sh</code>——无依赖的交互式编辑器（数字=切换，s=保存，q=退出，r=重置）</td><td>—</td></tr><tr><td>19</td><td><code>cache-stats</code></td><td>无</td><td>对 <code>$(OC_CACHE_DIR)/STATS</code> 跑 awk：HIT/MISS 计数、命中率 %、条目数；冷缓存打印 &quot;no STATS yet&quot;</td><td>永不失败</td></tr><tr><td>20</td><td><code>cache-clear</code></td><td>无</td><td><code>rm -rf $(OC_CACHE_DIR)</code></td><td>—</td></tr><tr><td>21</td><td><code>test</code></td><td>无</td><td><code>python3 tools/run_host_tests.py</code> 编译并运行每个 <code>tests/host_*.c</code> 测试桩</td><td><strong>退出码 = 失败测试数</strong></td></tr><tr><td>22</td><td><code>l0-i18n</code></td><td><code>$(L0_I18N_GEN)</code></td><td><code>tools/gen_l0_i18n.py</code> 从 <code>etc/i18n/l0/{en,zh}.json</code>（各 49 键）再生 <code>ocos/kernel/core_lib_i18n_data.c</code>；幂等</td><td>生成器失败即中止</td></tr><tr><td>23</td><td><code>userprogs</code></td><td><code>$(USERPROGS_HDR)</code></td><td><code>tools/gen_userprogs.py</code> 全量再生内嵌程序头文件（发现 + 注册表 + 孤儿清除，见 <a href="./guard-scripts.html">guard-scripts</a>）</td><td>任一程序的编译/链接失败即中止</td></tr><tr><td>24</td><td><code>userprogs-check</code></td><td>无</td><td>过期门禁：<code>ls -t $(USERPROG_SRCS)</code> 最新源对比头文件的 <code>stat -c %Y</code>；最新源新出 2 秒以上 → <code>ERROR: &lt;src&gt; is newer than userprogs_data.h</code> + <code>exit 1</code>（2 秒余量吸收全新克隆的 mtime 抖动）</td><td>exit 1；接入 <code>make dist</code></td></tr><tr><td>25</td><td><code>api-docs</code></td><td>无</td><td><code>tools/gen_api_docs.py --help-capture evidence/help_a_runtime.txt --l1-registry evidence/help_a_runtime.txt</code> → <code>docs/data/*.json</code></td><td>生成器失败即中止</td></tr><tr><td>26</td><td><code>FORCE</code></td><td><code>.PHONY</code></td><td>永远过期的辅助目标，驱动 cmp 守护的生成器</td><td>—</td></tr></tbody></table><h2 id="_3-内部文件目标" tabindex="-1">3. 内部文件目标 <a class="header-anchor" href="#_3-内部文件目标" aria-label="Permalink to &quot;3. 内部文件目标&quot;">​</a></h2><h3 id="_3-1-order-only-前置与生成头文件" tabindex="-1">3.1 order-only 前置与生成头文件 <a class="header-anchor" href="#_3-1-order-only-前置与生成头文件" aria-label="Permalink to &quot;3.1 order-only 前置与生成头文件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>目标</th><th>规则要点</th><th>存在原因</th></tr></thead><tbody><tr><td><code>$(BUILD)</code></td><td><code>mkdir -p build</code></td><td>每个目标文件的 order-only 前置条件</td></tr><tr><td><code>$(GEN_DIR)/version_gen.h</code></td><td><code>FORCE</code> + 写入 <code>.tmp</code>、<code>cmp -s</code> 守护、仅变更时 mv</td><td>产出 <code>#define OC_VERSION_STAMP &quot;&lt;ver&gt; build &lt;build&gt;&quot;</code>。<code>-D</code> 参数对 <code>-MMD</code> 不可见，因此增量构建曾保留过期横幅（WP-10-tui-qa：一个 ISO 在 <code>-ga29ac53</code> 的代码上启动了 <code>-ga4d5342</code> 横幅）。该头文件让版本变更对依赖图可见</td></tr><tr><td><code>$(GEN_DIR)/config_gen.h</code></td><td>同样的 cmp 守护模式</td><td>产出 <code>OC_CONFIG_NVME/AHCI/VIRTIO_BLK</code> 0/1，以及关闭时 <code>driver_block_&lt;x&gt;_init()</code> 的空操作桩；是 <code>$(KERNEL_OBJ) $(STUB_OBJ) $(GRUB_DATA_OBJ)</code> 的 order-only 前置条件——必须在任何目标文件编译前存在，但只有 <code>.d</code> 文件触发重建</td></tr></tbody></table><h3 id="_3-2-两阶段内核链接" tabindex="-1">3.2 两阶段内核链接 <a class="header-anchor" href="#_3-2-两阶段内核链接" aria-label="Permalink to &quot;3.2 两阶段内核链接&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>KERNEL_OBJ + grub_boot_stub.o --ld--&gt; build/opencube_base.elf (+strip)</span></span>
<span class="line"><span>embed_grub.py &quot;$(OC_TOOLS)&quot; base.elf --&gt; ocos/kernel/generated/grub_boot_data.c</span></span>
<span class="line"><span>grub_boot_data.c --compile--&gt; grub_boot_data.o</span></span>
<span class="line"><span>KERNEL_OBJ + grub_boot_data.o --ld--&gt; build/opencube.elf (+strip)</span></span></code></pre></div><ul><li><code>$(STUB_OBJ)</code>：<code>core_boot_grubstub.c</code> 单独编译（仅 stage-1 链接；从 <code>KERNEL_C</code> 中过滤掉）。</li><li><code>$(GRUB_DATA_C)</code>：<code>tools/embed_grub.py</code> 把 GRUB i386-pc 的 <code>boot.img</code>（512 B）+ <code>core.img</code>（grub-mkimage，带盘上 cfg 所需模块）作为 C 数组内嵌——内核内安装器的载荷。内核 ELF 本身不被内嵌（GRUB 经 grub.cfg 把它作为 multiboot2 模块 挂载）。</li><li><code>$(KERNEL)</code>：stage-2 链接还携带 <code>$(L0_I18N_GEN)</code> 和 <code>$(IME_PHRASE_GEN)</code> 作为前置条件，使 i18n/IME 表在链接时 是新鲜的。</li><li><code>-include $(KERNEL_OBJ:.o=.d)</code>：BUG-025 FIX——<code>-MMD -MP</code> 头文件跟踪。OCIRE 和 OCSE 出于同一原因各带自己的 <code>-include</code> 行。</li></ul><h3 id="_3-3-其他文件目标" tabindex="-1">3.3 其他文件目标 <a class="header-anchor" href="#_3-3-其他文件目标" aria-label="Permalink to &quot;3.3 其他文件目标&quot;">​</a></h3><table tabindex="0"><thead><tr><th>目标</th><th>逻辑</th></tr></thead><tbody><tr><td><code>$(ETC_IMG)</code> = <code>build/etc.img</code></td><td><code>truncate -s 32M</code>、带 <code>drive e:</code> 的 mtoolsrc、<code>mformat -F -v OCS_ETC e:</code>（FAT32）、<code>mcopy etc/opencube.conf</code>——持久的 <code>/etc</code> 卷（WP-09-fix5）</td></tr><tr><td><code>$(USERPROGS_HDR)</code> = <code>ocos/kernel/userprogs_data.h</code></td><td>真实文件目标：任一 <code>USERPROG_SRCS</code> 条目（或生成器脚本）更新 → <code>gen_userprogs.py</code>；幂等的字节比较式产出，因此已是最新状态的树不再重建任何东西</td></tr><tr><td><code>$(L0_I18N_GEN)</code></td><td><code>etc/i18n/l0/{en,zh}.json</code> 或生成器更新 → 再生</td></tr><tr><td><code>$(IME_PHRASE_GEN)</code> + 其 <code>.h</code></td><td><code>tools/ime_phrases.txt</code> 或 <code>gen_pinyin_phrase.py</code> 更新 → 再生</td></tr><tr><td><code>build/ocos/**/*..o</code></td><td>通用 <code>$(OC_CC) $(CFLAGS) -c</code>（即 <code>-O2</code>）</td></tr><tr><td><code>build/boot_%.o</code></td><td>对 <code>ocos/kernel/core_boot_*.S</code> 的 NASM <code>-f elf64 -F dwarf -g</code></td></tr><tr><td><code>build/core/arch/%.o</code></td><td>对 <code>ocos/kernel/arch/x86_64/*.S</code> 的 NASM</td></tr><tr><td><code>$(KERNEL_ISO)</code></td><td><code>bash tools/build_iso.sh</code>；前置条件：内核、<code>userprogs_data.h</code>、<code>ocbl_bios.bin</code>、<code>ocbl_x64.efi</code>、<code>ocire.elf</code>、脚本本身</td></tr><tr><td><code>$(SRC_ZIP)</code> / <code>.srclist</code> / <code>.taglist</code></td><td>见上文 <code>src-zip</code></td></tr></tbody></table><h2 id="_4-变量-完整清单" tabindex="-1">4. 变量（完整清单） <a class="header-anchor" href="#_4-变量-完整清单" aria-label="Permalink to &quot;4. 变量（完整清单）&quot;">​</a></h2><h3 id="_4-1-路径、工具、架构" tabindex="-1">4.1 路径、工具、架构 <a class="header-anchor" href="#_4-1-路径、工具、架构" aria-label="Permalink to &quot;4.1 路径、工具、架构&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>默认值 / 推导</th><th>含义</th></tr></thead><tbody><tr><td><code>OC_ROOT</code></td><td>Makefile 目录的 <code>abspath</code></td><td>仓库根</td></tr><tr><td><code>BUILD</code> / <code>ISO_DIR</code> / <code>DIST</code></td><td><code>$(OC_ROOT)/build</code>、<code>/iso</code>、<code>/dist</code></td><td>输出目录</td></tr><tr><td><code>ARCH</code></td><td><code>x86_64</code></td><td>目标机分派（<code>x86_64 arm64 riscv</code>，否则 <code>$(error)</code>）</td></tr><tr><td><code>CC</code> / <code>LD</code> / <code>NASM</code> / <code>QEMU</code></td><td><code>gcc</code> / <code>ld</code> / <code>nasm</code> / <code>qemu-system-x86_64</code></td><td>PATH 解析的工具</td></tr><tr><td><code>OC_TOOLS</code></td><td><code>/usr</code></td><td>迁移式工具链根（dpkg -x 树）；<code>build.sh</code> 自动检测</td></tr><tr><td><code>OVMF_FD</code></td><td><code>$(OC_TOOLS)/share/ovmf/OVMF.fd</code></td><td>UEFI 固件</td></tr><tr><td><code>QEMU_DATADIR</code></td><td><code>$(OC_TOOLS)/share/qemu</code></td><td>QEMU <code>-L</code> 路径</td></tr><tr><td><code>SEABIOS_DIR</code></td><td><code>$(OC_TOOLS)/share/seabios</code></td><td>BIOS 固件</td></tr><tr><td><code>CROSS</code>（架构构建）</td><td><code>aarch64-linux-gnu-</code> / <code>riscv64-linux-gnu-</code></td><td>交叉前缀</td></tr></tbody></table><h3 id="_4-2-版本与标识" tabindex="-1">4.2 版本与标识 <a class="header-anchor" href="#_4-2-版本与标识" aria-label="Permalink to &quot;4.2 版本与标识&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>默认值</th><th>含义</th></tr></thead><tbody><tr><td><code>OC_RELEASE_VERSION</code></td><td><code>3.0.0-NAK</code>（固定字面量；<code>?=</code> 覆盖优先）</td><td>内核横幅 / <code>uname</code> / 更新检查字符串；按 E2E 更新测试覆盖，例如 <code>make OC_RELEASE_VERSION=WP-10c-test1</code></td></tr><tr><td><code>OC_KERNEL_BUILD_OFFSET</code></td><td><code>21</code></td><td>在 <code>git rev-list --count HEAD</code> 之上的对齐偏移；保持数值型 OTA 比较在已发布 id 278/321/414/416 之上单调（BUG-0347）</td></tr><tr><td><code>OC_KERNEL_BUILD</code></td><td><code>expr git rev-list --count HEAD + 21</code></td><td>单调构建 id；覆盖方式 <code>make OC_KERNEL_BUILD=42</code></td></tr></tbody></table><h3 id="_4-3-配置" tabindex="-1">4.3 配置 <a class="header-anchor" href="#_4-3-配置" aria-label="Permalink to &quot;4.3 配置&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>默认值</th><th>效果</th></tr></thead><tbody><tr><td><code>CONFIG_NVME</code> / <code>CONFIG_AHCI</code> / <code>CONFIG_VIRTIO_BLK</code></td><td><code>y</code>（存在 <code>.config</code> 时取自其中）</td><td><code>=n</code> 把该驱动 <code>.c</code> 从 <code>KERNEL_C</code> 过滤掉，并经 <code>config_gen.h</code> 把它的 init 调用替换为桩</td></tr><tr><td><code>.config</code></td><td>（可选）</td><td>由 <code>defconfig</code>/<code>menuconfig</code> 写入的 make 片段；命令行覆盖优先</td></tr></tbody></table><h3 id="_4-4-源与目标文件" tabindex="-1">4.4 源与目标文件 <a class="header-anchor" href="#_4-4-源与目标文件" aria-label="Permalink to &quot;4.4 源与目标文件&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>内容</th></tr></thead><tbody><tr><td><code>KERNEL_DIRS</code></td><td><code>ocos/kernel</code>、<code>ocos/kernel/arch/x86_64</code>、<code>ocos/services</code>、<code>ocos/drivers</code> + <code>ocos/services/*/src</code>、<code>ocos/drivers/*/</code> 的通配</td></tr><tr><td><code>KERNEL_INC</code></td><td>每个 <code>KERNEL_DIRS</code> 的 <code>-I</code> + <code>tools</code> + <code>ocos/services/*/interface</code> + <code>ocos/kernel/generated</code> + <code>include</code>（多 <code>-I</code> 纯基名 include 策略）</td></tr><tr><td><code>KERNEL_C</code></td><td>对 <code>KERNEL_DIRS</code> 的 <code>*.c</code> 通配，减去 <code>core_boot_grubstub.c</code>，减去被配置过滤的驱动</td></tr><tr><td><code>KERNEL_ASM_B</code> / <code>KERNEL_ASM_K</code></td><td><code>ocos/kernel/core_boot_*.S</code> / <code>ocos/kernel/arch/x86_64/*.S</code></td></tr><tr><td><code>KERNEL_OBJ</code></td><td>模式替换 <code>.c→.o</code>（build 镜像）、boot <code>.S→boot_%.o</code>、arch <code>.S→core/arch/%.o</code></td></tr><tr><td><code>KERNEL</code> / <code>KERNEL_ISO</code></td><td><code>build/opencube.elf</code> / <code>build/opencube.iso</code></td></tr><tr><td><code>GEN_DIR</code> / <code>GRUB_DATA_C</code> / <code>GRUB_DATA_OBJ</code> / <code>STUB_OBJ</code> / <code>BASE_ELF</code></td><td>生成目录 + 两阶段链接集合</td></tr><tr><td><code>VERSION_GEN</code> / <code>CONFIG_GEN</code></td><td>cmp 守护的生成头文件</td></tr><tr><td><code>EMBED_PY</code> / <code>BUILD_C_PY</code> / <code>BUILD_SOLIB_PY</code></td><td><code>tools/embed_userprog.py</code> / <code>build_c_userprog.py</code> / <code>build_solib.py</code></td></tr></tbody></table><h3 id="_4-5-内嵌程序、打包、缓存" tabindex="-1">4.5 内嵌程序、打包、缓存 <a class="header-anchor" href="#_4-5-内嵌程序、打包、缓存" aria-label="Permalink to &quot;4.5 内嵌程序、打包、缓存&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>内容</th></tr></thead><tbody><tr><td><code>USERPROG_SRCS</code></td><td>对 <code>ocos/l1apps/*.{asm,c}</code>、<code>ld_so.c</code>、<code>*/*.c</code>、<code>*/*.asm</code>、<code>ocos/interface/*.h</code>、<code>*/i18n/*.json</code>、<code>_i18n/*/*.json</code> 的通配（json 在 WP06g2 的 548 文件提示清扫现场抓出后加入）</td></tr><tr><td><code>USERPROGS_HDR</code></td><td><code>ocos/kernel/userprogs_data.h</code></td></tr><tr><td><code>ETC_IMG</code></td><td><code>build/etc.img</code></td></tr><tr><td><code>SRC_ZIP</code> / <code>SRC_EXCLUDE</code> / <code>SRC_REV</code></td><td><code>dist/OpenCubeOS-src-&lt;ver&gt;.zip</code>；排除 <code>website/public/downloads website/out website/.next website/node_modules build dist releases .zscripts public/deliverables evidence archive trash</code>；rev = tag <code>v&lt;ver&gt;</code>，否则 <code>HEAD</code></td></tr><tr><td><code>OTA_PKG</code></td><td><code>dist/OpenCubeOS-&lt;ver&gt;-update.tar.gz</code></td></tr><tr><td><code>OC_CACHE_DIR</code></td><td><code>$(HOME)/.cache/opencube-cc</code></td></tr><tr><td><code>L0_I18N_GEN</code> / <code>IME_PHRASE_GEN</code></td><td>生成的 i18n/IME 源</td></tr></tbody></table><h3 id="_4-6-参数" tabindex="-1">4.6 参数 <a class="header-anchor" href="#_4-6-参数" aria-label="Permalink to &quot;4.6 参数&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变量</th><th>值</th></tr></thead><tbody><tr><td><code>CFLAGS</code></td><td><code>-ffreestanding -fno-stack-protector -fno-pie -fno-pic -mno-red-zone -mno-sse -mno-mmx -mno-3dnow -mcmodel=kernel -fno-asynchronous-unwind-tables -Wall -Wextra -Werror -O2 -g -std=gnu11 $(KERNEL_INC) -DOC_RELEASE_VERSION=\\&quot;…\\&quot; -DOC_KERNEL_BUILD=N -MMD -MP</code></td></tr><tr><td><code>ASFLAGS</code></td><td><code>-f elf64 -F dwarf -g</code></td></tr><tr><td><code>OC_CC</code></td><td><code>bash tools/oc_cc.sh $(CC)</code>——编译缓存封装</td></tr><tr><td><code>LDFLAGS</code></td><td><code>-n -nostdlib -T ocos/kernel/arch/x86_64/linker.ld -z max-page-size=0x1000 -z noexecstack</code></td></tr></tbody></table><p><code>-Wall -Wextra -Werror</code> 三件套出现在每个组件的参数里（内核、 OCIRE、OCBL、OCSE、agent）——这是本项目的 &quot;lint&quot;；CI 在每次 推送时运行它（见 <a href="./ci-gates.html">ci-gates</a>）。</p><h2 id="_5-mk-包含文件" tabindex="-1">5. .mk 包含文件 <a class="header-anchor" href="#_5-mk-包含文件" aria-label="Permalink to &quot;5. .mk 包含文件&quot;">​</a></h2><h3 id="_5-1-ocire-mk-ocire-恢复内核——11-个伪目标" tabindex="-1">5.1 ocire.mk（OCIRE 恢复内核——11 个伪目标） <a class="header-anchor" href="#_5-1-ocire-mk-ocire-恢复内核——11-个伪目标" aria-label="Permalink to &quot;5.1 ocire.mk（OCIRE 恢复内核——11 个伪目标）&quot;">​</a></h3><p>独立内核：自己的参数（<code>OCIRE_CFLAGS</code>，同一 freestanding 集， 仅 <code>-I ocire -I ocire/generated -I include</code>）、自己的链接脚本 <code>ocire/linker_ocire.ld</code>、优先于通用 <code>$(BUILD)/%.o</code> 规则的静态 模式规则、自己的 <code>-include $(OCIRE_OBJ_C:.o=.d)</code>（在 WP-02 现场抓出过期的 OCIRE 目标文件向两个 MBR 写入垃圾起始 LBA 之后 加入）。<code>OCIRE_VERSION ?= $(OC_RELEASE_VERSION)</code>（BUG #92 修复 ——横幅曾落后四个里程碑）。内部生成器： <code>ocire/generated/ocire_cn_font_data.c</code>（OCSE 字体数据的 sed 改写，cmp 守护）和 <code>ocire_version_gen.h</code>（<code>OCIRE_STAMP</code>， cmp 守护）。</p><table tabindex="0"><thead><tr><th>目标</th><th>产物 / 逻辑</th></tr></thead><tbody><tr><td><code>ocire-agent</code></td><td>ring-3 日志代理，按 l1apps C 程序的方式编译（user.ld @ 0x400000、int 0x80）但独立交付 → <code>build/ocire/agent.elf</code></td></tr><tr><td><code>ocire-kernel</code></td><td><code>build/ocire/ocire.elf</code></td></tr><tr><td><code>ocire-iso</code></td><td><code>tools/build_ocire_iso.sh</code> → <code>build/ocire/ocire.iso</code></td></tr><tr><td><code>ocire-disk</code></td><td><code>tools/make_ocire_disk.sh</code> 双启动 + 恢复测试盘</td></tr><tr><td><code>ocire-run-bios</code> / <code>-uefi</code> / <code>-bios-gui</code> / <code>-uefi-gui</code></td><td>QEMU 运行（128M、自己的 <code>OVMF_OCIRE.fd</code> pflash 副本）</td></tr><tr><td><code>ocire-test</code></td><td><code>tools/run_ocire_tests.py</code>（boot/help/unknown/backspace/shutdown × BIOS+UEFI）</td></tr><tr><td><code>ocire-dual-test</code></td><td>双启动 + 分区隔离全套</td></tr><tr><td><code>ocire-shell-test</code></td><td>WP-02 第 4 组恢复 shell 全套（help/logread/syscheck/repair quick/full/return，含摘要损坏 + BPB 被清零）</td></tr></tbody></table><h3 id="_5-2-ocbl-mk-ocbl-引导加载器——双风味" tabindex="-1">5.2 ocbl.mk（OCBL 引导加载器——双风味） <a class="header-anchor" href="#_5-2-ocbl-mk-ocbl-引导加载器——双风味" aria-label="Permalink to &quot;5.2 ocbl.mk（OCBL 引导加载器——双风味）&quot;">​</a></h3><p>一棵源码树，两种风味：带 <code>-mcmodel=small</code> 的 <code>-DOCBL_FLAVOR_BIOS</code>，和带 <code>-mcmodel=large</code> 的 <code>-DOCBL_FLAVOR_UEFI</code>（每个地址都是 PE 转换器可重定位的 64 位 <code>movabs</code>）。内建的断言（违规即构建失败）：两种 stage1 风味都 恰好 512 B；<code>tramp16.bin</code> ≤ 0x300 B；<code>handoff_blob.bin</code> ≤ 0x1000 B；EFI PE 头检查（MZ / PE\\0\\0 / machine 0x8664 / subsystem 10）。<code>include/ocbl_state.h</code> 是每个 OCBL 目标文件的 前置条件（WP07a 过期地址现场抓出）。EFI 风味用 <code>--emit-relocs</code> 链接一个中间 ELF 并经 <code>ocbl/elf_to_efi.py</code> 转换（完整的 <code>.reloc</code> 目录；朴素的 <code>ld -m i386pep</code> 路线在 OVMF 下重定位 错误）。</p><p>伪目标：<code>ocbl-bios</code>（stage1 El Torito + MBR 风味 + core → <code>ocbl_bios.bin</code>、<code>stage1_mbr.bin</code>）、<code>ocbl-efi</code> （<code>ocbl_x64.efi</code>）、<code>ocbl-iso</code>（经 <code>ocbl/build_test_iso.py</code> 的 独立双固件测试 ISO——该脚本是硬前置条件，B1 现场抓出）、 <code>ocbl-run-bios</code>、<code>ocbl-run-uefi</code>、<code>ocbl-scan-disks</code>（经 <code>ocbl/make_scan_disks.py</code> 的 11 镜像机群；时间戳覆盖所有同级 镜像——B5-7 现场抓出）、<code>ocbl-run-scan</code>（启动机群：2 块 IDE 盘、3 块 virtio 盘、FAT + 裸镜像、1 张 CD + 测试 ISO）。</p><h3 id="_5-3-ocse-mk-ocse-安装环境" tabindex="-1">5.3 ocse.mk（OCSE 安装环境） <a class="header-anchor" href="#_5-3-ocse-mk-ocse-安装环境" aria-label="Permalink to &quot;5.3 ocse.mk（OCSE 安装环境）&quot;">​</a></h3><ul><li><code>ocse-vendor-check</code>——<code>ocse/kernel/types.h</code> 缺失即失败： &quot;run <code>tools/vendor_ocse.sh</code> then <code>tools/ocse_edits.py</code>&quot;。作为 每个 <code>make ocse-elf</code> 的前置条件运行。</li><li><code>ocse-elf</code> → <code>build/ocse/ocse.elf</code>（单阶段链接、输出 <code>-Map=</code>、 <code>filter-out driver_block_disk_setup.c</code>——GRUB 时代的工具；该 过滤行逐字重复了 10 次，一个已知的外观瑕疵）。</li><li><code>ocse-iso</code> → <code>bash tools/build_ocse_iso.sh</code>，它先对 ELF 运行 <code>tools/check_bss.py</code>（见 <a href="./guard-scripts.html">guard-scripts</a>）。</li><li><code>ocse-clean</code>；自己的 <code>-include $(OCSE_OBJ:.o=.d)</code>。</li><li><code>OCSE_CFLAGS</code> 镜像内核参数集 + <code>-DOCSE_RELEASE=\\&quot;&lt;ver&gt;-ocse\\&quot;</code><ul><li><code>-DOCSE_BUILD</code>。</li></ul></li></ul><h3 id="_5-4-arm64-riscv-build-mk-各-4-个目标" tabindex="-1">5.4 arm64 / riscv build.mk（各 4 个目标） <a class="header-anchor" href="#_5-4-arm64-riscv-build-mk-各-4-个目标" aria-label="Permalink to &quot;5.4 arm64 / riscv build.mk（各 4 个目标）&quot;">​</a></h3><p><code>make ARCH=arm64|riscv</code> 替换整个 x86_64 主体。工具链 <code>CROSS ?= aarch64-linux-gnu-</code> / <code>riscv64-linux-gnu-</code>（Debian <code>gcc-aarch64-linux-gnu</code> / <code>gcc-riscv64-linux-gnu</code>，GCC ≥ 12）。 源码：<code>src/L0/core/arch/&lt;arch&gt;/{boot.S,kernel_main.c}</code>（裸机 入口 + UART + 心跳）。<code>XCFLAGS</code>：freestanding + <code>-mgeneral-regs-only</code>（arm64）/ <code>-march=rv64imac_zicsr -mabi=lp64 -mcmodel=medany</code>（riscv——无 FP：裸 <code>-kernel</code> 启动的 M-mode 没有 编程 <code>mstatus.FS</code>），两者都带 <code>-Wall -Wextra -Werror -O2 -g -std=gnu11 -DOC_RELEASE_VERSION -DOC_KERNEL_BUILD</code>。目标： <code>all</code>/<code>kernel</code> → <code>build/opencube-&lt;arch&gt;.elf</code>（+ readelf Class/Machine/Entry 回显）、<code>run-bios</code> → <code>qemu-system-&lt;arch&gt; -machine virt [-cpu cortex-a57] -nographic -kernel</code>、<code>clean-arch</code>。 链接：<code>$(XCC) -T linker.ld -Wl,--build-id=none -Wl,--hash-style=sysv</code>。</p><h2 id="_6-d-宏表-全部构建期定义" tabindex="-1">6. -D 宏表（全部构建期定义） <a class="header-anchor" href="#_6-d-宏表-全部构建期定义" aria-label="Permalink to &quot;6. -D 宏表（全部构建期定义）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宏</th><th>定义位置</th><th>启用什么</th></tr></thead><tbody><tr><td><code>OC_RELEASE_VERSION</code></td><td>kernel/OCSE/arch CFLAGS（字符串）</td><td>内核横幅、<code>uname</code>、更新检查版本串</td></tr><tr><td><code>OC_KERNEL_BUILD</code></td><td>kernel/OCSE/arch CFLAGS（数字）</td><td>被 OTA 检查按数值比较的单调构建 id（BUG-0347）</td></tr><tr><td><code>OCBL_RELEASE</code>、<code>OCBL_BUILD</code></td><td>ocbl.mk，两种风味</td><td>OCBL 横幅/版本</td></tr><tr><td><code>OCBL_FLAVOR_BIOS</code></td><td>ocbl.mk BIOS 目标文件</td><td>选择 int-13h/VGA/E820/VBE 后端实现（<code>ocbl/common/ocbl_main.c</code> 中的 <code>#ifdef</code> 位点）</td></tr><tr><td><code>OCBL_FLAVOR_UEFI</code></td><td>ocbl.mk EFI 目标文件</td><td>同一契约的 EFI 后端</td></tr><tr><td><code>OCSE_RELEASE</code>、<code>OCSE_BUILD</code></td><td>ocse.mk</td><td>OCSE 横幅（发布字面量 + <code>-ocse</code> 后缀）</td></tr><tr><td><code>OCBL_ELTORITO</code> / <code>OCBL_MBR</code></td><td><code>stage1.asm</code> 上的 NASM <code>-D</code></td><td>汇编哪种 512 字节 stage1 风味</td></tr><tr><td><code>OC_CONFIG_NVME</code> / <code>OC_CONFIG_AHCI</code> / <code>OC_CONFIG_VIRTIO_BLK</code></td><td>生成的 <code>config_gen.h</code>（0/1）</td><td>硬件画像；<code>0</code> 还把 <code>driver_block_&lt;x&gt;_init(...)</code> <code>#define</code> 成空操作桩</td></tr><tr><td><code>OC_VERSION_STAMP</code></td><td>生成的 <code>version_gen.h</code></td><td>触发重编译的字符串</td></tr><tr><td><code>OCIRE_STAMP</code></td><td>生成的 <code>ocire_version_gen.h</code></td><td>OCIRE 重编译触发器</td></tr><tr><td><code>RSA_DEBUG</code></td><td><strong>不在任何构建文件中</strong>——源码局部 <code>#ifdef</code>（<code>ocos/services/crypto/src/svc_crypto_rsa.c</code> 中 6 处）</td><td>RSA 路径的调试打印；编辑该文件顶部的 <code>#define</code> 启用</td></tr></tbody></table><p>构建文件中任何地方都<strong>没有</strong> <code>NAP_SANITIZE</code>、<code>DEBUG</code> 或 <code>OC_DEBUG</code> 构建宏：所有构建类型的 freestanding 参数完全相同； 宿主侧测试用各自的 gcc 行编译（若干在本地使用 ASAN，记录在 每个 <code>tests/host_*.c</code> 头部）。</p><h2 id="_7-按文件优化覆盖-9-×-os-1-×-o0" tabindex="-1">7. 按文件优化覆盖（9 × -Os，1 × -O0） <a class="header-anchor" href="#_7-按文件优化覆盖-9-×-os-1-×-o0" aria-label="Permalink to &quot;7. 按文件优化覆盖（9 × -Os，1 × -O0）&quot;">​</a></h2><p>所有覆盖使用同一模式： <code>$(OC_CC) $(filter-out -O2,$(CFLAGS)) -Os|-O0 -c $&lt; -o $@</code>。</p><table tabindex="0"><thead><tr><th>文件</th><th>级别</th><th>原因（来自 Makefile 注释）</th></tr></thead><tbody><tr><td><code>ocos/drivers/net/drv_net_wireless.c</code></td><td><code>-Os</code></td><td>无线/sd 驱动集——内核镜像必须留在 0x400000 恒等窗口内；链接器 ASSERT 按字节精确，<code>-O2</code> 实测超限 8 KiB</td></tr><tr><td><code>ocos/drivers/net/drv_net_iwlwifi.c</code></td><td><code>-Os</code></td><td>同一窗口纪律</td></tr><tr><td><code>ocos/drivers/net/drv_net_rtlwifi.c</code></td><td><code>-Os</code></td><td>同</td></tr><tr><td><code>ocos/drivers/net/drv_net_ath.c</code></td><td><code>-Os</code></td><td>同</td></tr><tr><td><code>ocos/drivers/net/drv_net_brcm.c</code></td><td><code>-Os</code></td><td>同</td></tr><tr><td><code>ocos/drivers/storage/drv_storage_sdhci.c</code></td><td><code>-Os</code></td><td>同</td></tr><tr><td><code>ocos/drivers/misc/drv_misc_mjpeg.c</code></td><td><code>-Os</code></td><td>代码生成敏感：<code>-O2</code> 错编一条可用路径（段错误被 4:4:4 宿主夹具抓到）；<code>-Os</code> 干净，且 JPEG 解码器不是性能关键</td></tr><tr><td><code>ocos/drivers/misc/drv_misc_camera.c</code></td><td><code>-Os</code></td><td>同一相机集原因</td></tr><tr><td><code>ocos/drivers/misc/drv_misc_camera_uvc.c</code></td><td><code>-Os</code></td><td>同</td></tr><tr><td><code>ocos/drivers/bus/drv_bus_acpi_aml.c</code></td><td><code>-O0</code></td><td>AML 解释器只在启动时运行一次；<code>-O2</code> 代码生成与重指针的值模型交互不良（kfree 中野指针导致启动崩溃），而 <code>-O0</code> 能干净解析现场 QEMU DSDT</td></tr></tbody></table><p>历史备注（NAK 清理）：针对根级 <code>tui/</code> 目录的两条 <code>-Os</code> 规则从未 匹配到真实目标文件，已被删除而非更新路径——现在激活它们会改变 一直以 <code>-O2</code> 交付的文件的代码生成。</p><h2 id="_8-并行度与编译缓存" tabindex="-1">8. 并行度与编译缓存 <a class="header-anchor" href="#_8-并行度与编译缓存" aria-label="Permalink to &quot;8. 并行度与编译缓存&quot;">​</a></h2><ul><li><strong>并行度</strong>：<code>make -j$(nproc)</code>（build.sh 的 <code>JOBS</code>，默认 <code>nproc</code>）。安全性来自每个目标文件的 <code>@mkdir -p $(dir $@)</code> 配方、order-only 前置条件（<code>| $(BUILD)</code>、<code>| $(VERSION_GEN) $(CONFIG_GEN)</code>）和永不搅动 mtime 的 cmp 守护生成器。</li><li><strong>编译缓存</strong>（<code>OC_CC := bash tools/oc_cc.sh $(CC)</code>）：缓存键 = 建立在（1）精确编译器身份（路径 + 版本串）、（2）完整参数表 （flags、<code>-D</code> 值、include 路径）、（3）源文件哈希、（4）源所 依赖的每个头文件的哈希（来自编译器自己的 <code>-MM</code> 输出——基于 内容，因此动了但内容没变的头文件仍然命中、mtime 没动但内容 变了的头文件仍然未命中）之上的 SHA-256。命中按字节一致还原 <code>.o</code> 和 <code>.d</code>；未命中则编译并把两者都存入。命中字节一致， 因此 <code>reproducible-check</code> 在缓存开启时依然有效。控制项： <code>OC_CACHE_DIR</code>（迁移）、<code>OC_CACHE_OFF</code>（绕过）；计数器落到 <code>$(OC_CACHE_DIR)/STATS</code>（由 <code>cache-stats</code> 读取）。</li><li><strong>增量完整性</strong>：所有 <code>.d</code> 文件的 <code>-include</code>（内核、OCIRE、 OCSE 各自包含自己的）、<code>version_gen.h</code> 重编译触发器，以及 <code>userprogs_data.h</code> 过期门禁，共同封住三类历史过期产物 （BUG-025、WP-10-tui-qa、WP06g1 catch-2）。</li></ul><h2 id="_9-生成但已提交的输入" tabindex="-1">9. 生成但已提交的输入 <a class="header-anchor" href="#_9-生成但已提交的输入" aria-label="Permalink to &quot;9. 生成但已提交的输入&quot;">​</a></h2><p>这些文件由 make 规则再生且已提交，因此全新的通配构建总能看到 它们：<code>ocos/kernel/userprogs_data.h</code>、 <code>ocos/kernel/core_lib_i18n_data.c</code>、 <code>ocos/kernel/generated/version_gen.h</code> / <code>config_gen.h</code>、 <code>ocos/kernel/generated/grub_boot_data.c</code>（仅 stage-2，不在 <code>KERNEL_DIRS</code> 中，瞬态）、<code>ocire/generated/ocire_cn_font_data.c</code> / <code>ocire_version_gen.h</code>、 <code>ocos/services/display/src/svc_display_pinyin_phrase_data.c</code>（+ <code>.h</code>）、<code>ocse/chinese/chinese_font_data.c</code>。绝不手工编辑它们； 每个文件对应的生成器见 <a href="./tool-inventory.html">tool-inventory</a>。</p><h2 id="_10-快速参考" tabindex="-1">10. 快速参考 <a class="header-anchor" href="#_10-快速参考" aria-label="Permalink to &quot;10. 快速参考&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make all                     # userprogs + kernel + ISO + src zip + OTA</span></span>
<span class="line"><span>make kernel | iso | src-zip | ota</span></span>
<span class="line"><span>make test                    # host unit harnesses</span></span>
<span class="line"><span>make run-bios | run-uefi | run-bios-gui | run-uefi-gui | run-*-persist</span></span>
<span class="line"><span>make shot-bios | shot-uefi</span></span>
<span class="line"><span>make reproducible-check</span></span>
<span class="line"><span>make defconfig | menuconfig</span></span>
<span class="line"><span>make cache-stats | cache-clear</span></span>
<span class="line"><span>make userprogs | userprogs-check</span></span>
<span class="line"><span>make l0-i18n | api-docs</span></span>
<span class="line"><span>make ocire-kernel | ocire-iso | ocire-test | ocire-disk | ocire-shell-test</span></span>
<span class="line"><span>make ocbl-bios | ocbl-efi | ocbl-iso | ocbl-run-scan</span></span>
<span class="line"><span>make ocse-elf | ocse-iso</span></span>
<span class="line"><span>make ARCH=arm64 | ARCH=riscv</span></span></code></pre></div>`,59)])])}const u=e(r,[["render",a]]);export{b as __pageData,u as default};
